SELECT *
FROM stock_watch_price_failure_ledger
WHERE rule_version = #{ruleVersion}
  AND sample_role = 'SIGNAL'
  AND symbol = #{symbol}
  AND market = #{market}
  AND source_date = #{sourceDate}
ORDER BY id ASC
LIMIT 1

SELECT *
FROM stock_watch_price_failure_ledger
WHERE rule_version = #{ruleVersion}
  AND status IN ('WAITING_ENTRY', 'WAITING_T1')
ORDER BY id ASC
LIMIT #{limit}
